/**
 * Content model for the forms guides, the downloads directory and the
 * articles (Stream C). Data files under `content/guides/` and
 * `content/articles/` are generated by `scripts/build-guides.mjs` from the
 * client handoffs; the copy is never reworded there.
 *
 * Text blocks reuse the `Span` convention of `content/types.ts`: plain text
 * plus spans matched by text (`a` = link, `b` = bold). Token references
 * (`{{M-19.medianDays}}`) are resolved at render time.
 */
import type { FaqItem, Span } from '../types';

export interface Rich {
  x: string;
  sp: Span[];
}

/** Placeholders the copy leaves for the platform tools. */
export type ToolKind =
  | 'checker'
  | 'calculator'
  | 'waiting'
  | 'office-finder'
  | 'assessment'
  | 'processing-chart';

export type ArticleBlock =
  | ({ t: 'p' } & Rich)
  | { t: 'h2'; x: string; id: string }
  | { t: 'h3'; x: string }
  /** Blockquote from the copy (ID-02 disclaimer) — rendered as a callout. */
  | ({ t: 'quote' } & Rich)
  /** Italic aside from the copy. */
  | ({ t: 'note' } & Rich)
  | { t: 'ul'; items: Rich[] }
  | { t: 'ol'; items: Rich[] }
  /** First row = header. */
  | { t: 'table'; rows: string[][] }
  /** Label / value rows (the processing-time "at a glance" block). */
  | { t: 'kv'; rows: string[][] }
  /** Sources / official-basis line. */
  | ({ t: 'src' } & Rich)
  /** Position of the FAQ section (`faq` items) inside the body. */
  | { t: 'faq' }
  | { t: 'tool'; kind: ToolKind }
  /** Registry-driven official-downloads list for the given form numbers. */
  | { t: 'downloads'; forms: string[] };

export interface ArticleFaqItem extends FaqItem {
  /**
   * Visible answer when it is richer than the plain `a` (links, several
   * paragraphs). `a` always carries the plain text used for the schema.
   */
  blocks?: ArticleBlock[];
}

export interface Crumb {
  label: string;
  href?: string;
}

export interface Cta {
  label: string;
  href: string;
}

export type ArticleKind = 'guide' | 'post' | 'evergreen' | 'collection';

export interface ArticleData {
  /** Site path, e.g. `/v0901-pension-refund-form-english`. */
  path: string;
  kind: ArticleKind;
  lang: 'en' | 'de';
  /** Title tag, exactly as given in the handoff. */
  title: string;
  /** Meta description, exactly as given in the handoff. */
  meta: string;
  h1: string;
  /** Schema headline (title tag without the "(2026)" suffix). */
  headline: string;
  /** Hero eyebrow, e.g. "Form guide · V0901" (design element). */
  eyebrow: string;
  /** Left-rail label (design element). */
  rail: string;
  /** Visible breadcrumb; the schema breadcrumb is Home → headline. */
  crumbs: Crumb[];
  /** "Last checked: …" / "Updated: …" line under the H1; tokens allowed. */
  reviewLine?: string;
  /** Show the reviewer/author name in the hero line. */
  showReviewer: boolean;
  datePublished: string;
  dateModified: string;
  imageUrl?: string;
  blocks: ArticleBlock[];
  /** Heading text of the FAQ section (where a `faq` block exists). */
  faqTitle?: string;
  faq: ArticleFaqItem[];
  /** Whether the page emits a FAQPage node at all. */
  faqInSchema: boolean;
  /** Pill CTAs at the end of the column. */
  cta: Cta[];
  /** Handoff provenance, for the report only. */
  source: string;
}
